/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountStoryProgress, type StoryProgressOptions } from "../../components/story-progress/StoryProgressEngine.js";
import type { MotionController } from "../../components/story-progress/motion-runtime";

export function StoryProgress({ options, className }: { options?: StoryProgressOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountStoryProgress(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="story-progress" />;
}

